<script setup lang="ts">
import { computed,nextTick } from 'vue';import { useRouter,useRoute } from 'vue-router';import { state,prepare,run,openServer,hasUnsentSession } from '../store';
const router=useRouter(),route=useRoute();
const rows=computed(()=>[...state.drafts.map(d=>({key:d.key,id:d.serverId,group_id:d.group_id,timestamp:d.timestamp,status:d.status,sync:d.sync,count:d.students.length})),...(state.cache?.sessions||[]).filter(s=>!state.drafts.some(d=>d.serverId===s.id)).map(s=>({key:'',id:s.id,group_id:s.group?.id,timestamp:s.timestamp,status:s.status,sync:'synced',count:s.students.length}))].sort((a,b)=>Date.parse(b.timestamp)-Date.parse(a.timestamp)));
const activeSession=computed(()=>hasUnsentSession());
const pageSize=10;
const totalPages=computed(()=>Math.max(1,Math.ceil(rows.value.length/pageSize)));
const page=computed(()=>{const requested=Number(route.query.page??state.sessionPage);return Number.isInteger(requested)?Math.max(1,Math.min(requested,totalPages.value)):1});
const visibleRows=computed(()=>rows.value.slice((page.value-1)*pageSize,page.value*pageSize));
const rangeStart=computed(()=>rows.value.length?(page.value-1)*pageSize+1:0);
const rangeEnd=computed(()=>Math.min(page.value*pageSize,rows.value.length));
const pageLinks=computed(()=>{const numbers=[...new Set([1,totalPages.value,...Array.from({length:3},(_,i)=>page.value+i-1).filter(n=>n>=1&&n<=totalPages.value)])].sort((a,b)=>a-b);const links:(number|string)[]=[];numbers.forEach((n,i)=>{if(i&&n-numbers[i-1]>1)links.push('gap-'+n);links.push(n)});return links});
async function goToPage(target:number){if(target<1||target>totalPages.value)return;state.sessionPage=target;await router.replace({path:'/',query:{...route.query,page:target===1?undefined:String(target)}});await nextTick();window.scrollTo({top:0,behavior:'instant'});document.querySelector<HTMLElement>('.sessions-pagination [aria-current="page"]')?.focus({preventScroll:true})}
const labels:Record<string,string>={local_only:'لم تُرسل',pending_upload:'بانتظار الإرسال',uploading:'جارٍ الإرسال',synced:'تم الإرسال',conflict:'بحاجة لمراجعة'};
async function open(row:typeof rows.value[number]){await run(async()=>{const key=row.key||(await openServer(row.id!)).key;await router.push('/session/'+key)})}
</script>
<template><section><div class="home-toolbar"><div class="page-title"><div><p class="eyebrow">السلام عليكم، {{state.auth?.profile.name}}</p><h1>حصصي</h1></div><button class="quiet" :disabled="state.busy||!state.online" @click="run(prepare)">{{state.busy?'جارٍ التحديث…':'تحديث'}}</button></div><RouterLink v-if="activeSession" class="primary create-session" :to="`/session/${activeSession.key}`">متابعة الحصة الحالية</RouterLink><button v-else class="primary create-session" :disabled="!state.online||!state.cache||state.busy" @click="router.push('/new')">+ إنشاء حصة</button></div><div class="cache-note"><span>{{state.cache?`آخر تحديث: ${new Date(state.cache.preparedAt).toLocaleString('ar')}`:'اتصل بالإنترنت لتحميل الحصص وبدء حصة جديدة.'}}</span><span v-if="activeSession">حصة واحدة قيد العمل أو الإرسال</span></div><div v-if="!rows.length" class="empty"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18"/></svg><h2>تبدأ الرحلة بحصة</h2><p>أنشئ حصة واختر المجموعة، ثم تابع كل طالب على حدة.</p></div><div v-else class="session-grid"><button v-for="row in visibleRows" :key="row.key||row.id" class="session-card" @click="open(row)"><div class="session-card-body"><div class="session-card-heading"><strong :title="state.cache?.groups.find(g=>g.id===row.group_id)?.name||'حصة محفوظة'">{{state.cache?.groups.find(g=>g.id===row.group_id)?.name||'حصة محفوظة'}}</strong><time class="session-card-date" :datetime="row.timestamp">{{new Date(row.timestamp).toLocaleDateString('ar',{day:'numeric',month:'short',year:'numeric'})}}</time></div><div class="session-card-meta"><div class="session-card-details"><time :datetime="row.timestamp">{{new Date(row.timestamp).toLocaleTimeString('ar',{hour:'numeric',minute:'2-digit'})}}</time><span class="session-card-roster">{{row.count}} {{row.count===1?'طالب':'طلاب'}} · {{row.status==='completed'?'مكتملة':'قيد التسجيل'}}</span></div><span class="badge" :class="row.sync">{{labels[row.sync]}}</span></div></div><svg class="session-card-arrow" viewBox="0 0 24 24" aria-hidden="true"><path d="m14 7-5 5 5 5"/></svg></button></div><div v-if="rows.length" class="sessions-page-summary" role="status">عرض {{rangeStart}}–{{rangeEnd}} من {{rows.length}} حصة</div><nav v-if="totalPages>1" class="sessions-pagination" aria-label="صفحات الحصص"><button class="quiet" :disabled="page===1" @click="goToPage(page-1)" aria-label="صفحة الحصص السابقة">→ السابق</button><template v-for="link in pageLinks" :key="link"><button v-if="typeof link==='number'" class="page-number" :aria-current="page===link?'page':undefined" :aria-label="'الصفحة '+link" @click="goToPage(link)">{{link}}</button><span v-else class="page-gap" aria-hidden="true">…</span></template><button class="quiet" :disabled="page===totalPages" @click="goToPage(page+1)" aria-label="صفحة الحصص التالية">التالي ←</button></nav></section></template>
